{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Outcome-focused wellness coaching in {{CITY}}, {{STATE}} — sustainable habits, clear frameworks, measurable progress.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav id="main-nav" class="nav">
        <a href="index.html">Home</a>
        <a href="about.html">Philosophy</a>
        <a href="programs.html">Paths</a>
        <a href="pricing.html">Investment</a>
        <a href="testimonials.html">Stories</a>
        <a href="book.html" class="cta small">Book</a>
      </nav>
      <button id="nav-toggle" class="nav-toggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <section id="hero" class="hero">
      <div class="container hero-inner">
        <div class="hero-copy">
          <h1 class="eyebrow">Clarity. Habit. Momentum.</h1>
          <h2 class="title">Transform daily routines into measurable wellbeing with {{COACH_NAME}}, {{CREDENTIALS}}</h2>
          <p class="lead">A structured coaching approach that prioritizes small, repeatable wins — designed for busy professionals in {{CITY}}, {{STATE}} seeking durable change.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="#lead-magnet">Download the Habit Map</a>
          </div>
        </div>
        <div class="hero-art">
          <img src="assets/img/hero.svg" alt="Abstract person practicing calm" />
        </div>
      </div>
    </section>

    <section id="values" class="values">
      <div class="container">
        <h3 class="section-title">Core Principles</h3>
        <div class="grid">
          <div class="card">
            <h4>Outcome-led</h4>
            <p>We start with the result you want and reverse-engineer reliable daily actions to get you there.</p>
          </div>
          <div class="card">
            <h4>Sustainable Habits</h4>
            <p>Small, science-aligned steps that stack into meaningful progress without overload.</p>
          </div>
          <div class="card">
            <h4>Accountable Frameworks</h4>
            <p>Simple tracking and weekly checkpoints to keep momentum and adapt what’s not working.</p>
          </div>
        </div>
      </div>
    </section>

    <section id="methods" class="methods">
      <div class="container">
        <h3 class="section-title">How We Work</h3>
        <ol class="process">
          <li>
            <strong>Discover</strong>
            <p>Clarify your priorities, constraints, and meaningful measures of success.</p>
          </li>
          <li>
            <strong>Design</strong>
            <p>Create a compact set of daily anchors and a weekly review that fits your life.</p>
          </li>
          <li>
            <strong>Deliver</strong>
            <p>Track progress, remove friction, and iterate weekly so small wins add up.</p>
          </li>
        </ol>
      </div>
    </section>

    <section id="objections" class="objections">
      <div class="container">
        <h3 class="section-title">Common Concerns — Answered</h3>
        <div class="faq-grid">
          <div class="faq">
            <h4>Will I need big lifestyle changes?</h4>
            <p>No. The focus is on minimal, high-leverage shifts you can repeat. The plan scales only if you want more progress.</p>
          </div>
          <div class="faq">
            <h4>Is this clinical advice?</h4>
            <p>This coaching focuses on habits and frameworks, not medical diagnosis. I work alongside your medical providers when needed.</p>
          </div>
          <div class="faq">
            <h4>What if I’m short on time?</h4>
            <p>Programs are built for busy schedules: 10–30 minutes of daily actions and a focused weekly session to keep you on track.</p>
          </div>
        </div>
      </div>
    </section>

    <section id="testimonials" class="testimonials">
      <div class="container">
        <h3 class="section-title">Client Results</h3>
        <div class="testi-list">
          <figure class="testi">
            <img src="assets/img/avatar.svg" alt="Client photo" />
            <blockquote>"I replaced overwhelm with a 15-minute morning routine that actually works. Three months in and I have energy every afternoon."</blockquote>
            <figcaption>— A fellow professional, {{CITY}}</figcaption>
          </figure>
          <figure class="testi">
            <img src="assets/img/avatar.svg" alt="Client photo" />
            <blockquote>"Clear checkpoints made accountability simple. I hit goals I had tried for years in half the time."</blockquote>
            <figcaption>— Entrepreneur, {{STATE}}</figcaption>
          </figure>
        </div>
      </div>
    </section>

    <section id="lead-magnet" class="lead-magnet">
      <div class="container">
        <h3 class="section-title">Free Habit Map</h3>
        <p>Download a practical 7-day map that shows how to embed one high-impact habit into your week. Instant PDF — no fluff.</p>
        <form id="magnet-form" class="magnet-form">
          <label for="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@company.com" required />
          <button class="btn primary" type="submit">Send the Habit Map</button>
          <p class="fine-print">We respect your privacy. Your email is used only to send the resource and occasional coaching updates.</p>
        </form>
        <div id="magnet-success" class="hidden">Thanks — check your inbox for the Habit Map.</div>
      </div>
    </section>

    <section id="cta" class="final-cta">
      <div class="container cta-inner">
        <h3>Ready to Rebuild Your Routines?</h3>
        <p>Work directly with {{COACH_NAME}}, {{CREDENTIALS}} — bespoke coaching that prioritizes progress over perfection.</p>
        <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="contact-small">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved.</p>
      <nav class="footer-nav">
        <a href="privacy.html">Privacy</a>
        <a href="contact.html">Contact</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
