{"path":"assets/css/styles.css","content":"/* Zen minimal — clean, spacious, intentional */
:root{
  --bg:#ffffff;--text:#0b1220;--muted:#6b7280;--accent:#0f766e;--accent-2:#06b6d4;--radius:10px;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;background:var(--bg);color:var(--text);font-size:16px;line-height:1.5}
.container{width:100%;max-width:var(--max-width);margin:0 auto;padding:32px}
.header-inner{display:flex;align-items:center;justify-content:space-between;padding:16px 0}
.brand{font-weight:700;letter-spacing:0.2px;color:var(--text);text-decoration:none}
.nav{display:flex;gap:18px;align-items:center}
.nav a{color:var(--muted);text-decoration:none;padding:6px 8px;border-radius:6px}
.nav a.cta{background:transparent;border:1px solid var(--accent);color:var(--accent);padding:8px 12px}
.nav-toggle{display:none;background:transparent;border:0;font-size:20px}
.hero{padding:56px 0}
.hero-inner{display:grid;grid-template-columns:1fr 420px;gap:40px;align-items:center}
.eyebrow{color:var(--accent);font-weight:700;margin:0 0 8px}
.title{font-size:28px;margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-actions{display:flex;gap:12px}
.btn{display:inline-block;text-decoration:none;padding:10px 16px;border-radius:8px;border:1px solid transparent}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border:1px solid #e6eef0;color:var(--text)}
.btn.small{padding:6px 10px}
.hero-art img{width:100%;height:auto;display:block}
.values,.methods,.objections,.testimonials,.lead-magnet,.final-cta{padding:40px 0}
.section-title{font-size:18px;color:var(--text);margin-bottom:18px}
.grid{display:flex;gap:18px}
.card{background:#fbfcfd;border-radius:var(--radius);padding:18px;flex:1;box-shadow:0 6px 18px rgba(10,10,10,0.03)}
.process{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:12px}
.process li{background:#fff;padding:14px;border-radius:8px;border:1px solid #f2f6f7}
.faq-grid{display:flex;gap:16px}
.faq{background:#fff;padding:14px;border-radius:8px;border:1px solid #f3f7f8}
.testi-list{display:flex;flex-direction:row;gap:18px}
.testi{background:#fff;padding:14px;border-radius:10px;border:1px solid #eef4f4;flex:1}
.testi img{width:56px;height:56px;border-radius:50%;object-fit:cover;margin-bottom:10px}
.lead-magnet .magnet-form{display:flex;gap:12px;align-items:center}
.magnet-form input[type="email"]{flex:1;padding:10px;border-radius:8px;border:1px solid #e6eef0}
.fine-print{font-size:13px;color:var(--muted);margin-top:8px}
.hidden{display:none}
.final-cta{background:linear-gradient(180deg,#f8fdfc,#ffffff);border-radius:12px}
.cta-inner{text-align:center;padding:30px}
.btn.large{padding:14px 22px;font-size:16px}
.site-footer{border-top:1px solid #eef4f4;padding:18px 0;margin-top:30px}
.footer-inner{display:flex;justify-content:space-between;align-items:center}
.footer-nav a{color:var(--muted);text-decoration:none;margin-left:10px}
@media (max-width:900px){
  .hero-inner{grid-template-columns:1fr;}
  .nav{display:none}
  .nav-toggle{display:block}
  .grid,.faq-grid,.testi-list{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // small interactive helpers: nav toggle, year, lead magnet form
  document.addEventListener('DOMContentLoaded',function(){
    var navToggle=document.getElementById('nav-toggle');
    var nav=document.getElementById('main-nav');
    if(navToggle){navToggle.addEventListener('click',function(){
      nav.classList.toggle('open');
      navToggle.setAttribute('aria-expanded',nav.classList.contains('open'));
    });}

    // year
    var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

    // lead magnet form
    var form=document.getElementById('magnet-form');
    var success=document.getElementById('magnet-success');
    if(form){
      form.addEventListener('submit',function(e){
        e.preventDefault();
        var email=form.email.value.trim();
        if(!email || email.indexOf('@')===-1){
          form.email.focus();
          return;
        }
        try{localStorage.setItem('lead_email',email);}catch(err){}
        form.classList.add('hidden');
        if(success) success.classList.remove('hidden');
        // simulate download link open
        setTimeout(function(){
          window.open('/assets/Habit-Map.pdf','_blank');
        },600);
      });
    }

    // smooth in-page scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(function(a){
      a.addEventListener('click',function(e){
        var target=document.querySelector(this.getAttribute('href'));
        if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth',block:'start'});} 
      });
    });
  });
})();
"} 
